window.HOEREN_TESTS[81] = {"id":"bei-der-autovermietung","name":"Bei der Autovermietung","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Guten Tag, hier ist die Autovermietung Fix. Ihr gebuchtes Auto ist leider nicht da — der letzte Kunde hatte einen Unfall. Aber wir haben ein größeres für Sie, zum gleichen Preis, kein kleineres und nicht gar keins. Ein kostenloses Upgrade sozusagen. Sie können es ab 10 Uhr abholen. Wir entschuldigen uns für die Umstände!","gender":"f","q":"Welches Auto bekommt der Kunde?","opts":["Ein kleineres.","Ein größeres zum gleichen Preis.","Gar keins."],"correct":1},{"transcript":"Hallo Tom, hier ist Markus. Pass auf, ich miete für den Umzug am Samstag einen Transporter, keinen Sportwagen und kein Fahrrad. Allein schaffe ich das nicht mit all den Möbeln. Kannst du mir helfen? Wir fahren zweimal, dann ist alles drüben. Ich gebe dir auch was fürs Benzin. Bitte sag ja, ruf zurück! Danke dir!","gender":"m","q":"Was mietet Markus?","opts":["Einen Sportwagen.","Ein Fahrrad.","Einen Transporter."],"correct":2},{"transcript":"Achtung Kunden: Bitte geben Sie das Auto immer vollgetankt zurück, nicht leer und nicht halb voll. Wenn der Tank nicht voll ist, tanken wir nach, aber das ist viel teurer als an der Tankstelle. Auch die Reinigung kostet extra, wenn das Auto sehr schmutzig ist. Bringen Sie es sauber und voll zurück. Vielen Dank!","gender":"m","q":"Wie soll man das Auto zurückgeben?","opts":["Leer.","Vollgetankt.","Halb voll."],"correct":1},{"transcript":"Hi Lisa, hier ist Anna. Im Urlaub haben wir ein Auto gemietet, aber pass auf: Lies immer den Vertrag genau! Wir mussten am Ende extra für eine kleine Versicherung zahlen, die nicht im Preis enthalten war. Es ging nicht um schlechte Autos und nicht um lange Wartezeiten. Frag immer nach, was alles dabei ist. Nächstes Mal mache ich es besser!","gender":"f","q":"Wovor warnt Anna?","opts":["Vor versteckten Kosten im Vertrag.","Vor schlechten Autos.","Vor langen Wartezeiten."],"correct":0},{"transcript":"Liebe Kunden: Ab sofort bieten wir auch Carsharing über eine App an, keine Fahrräder und keinen Lieferservice. Sie buchen ein Auto über die App, für eine Stunde oder einen ganzen Tag. Perfekt für kurze Fahrten in der Stadt, wenn Sie kein eigenes Auto haben. Die Autos stehen an vielen Stellen in der Stadt. Laden Sie die App herunter!","gender":"f","q":"Was bietet die Firma jetzt neu an?","opts":["Fahrräder.","Einen Lieferservice.","Carsharing über eine App."],"correct":2}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch. Sie hören den Text einmal. Wer mietet was? Wählen Sie für jede Person einen Buchstaben (a–i).","lines":[{"speaker":"Lukas","gender":"m","text":"Hallo Lisa! Am Schalter liegt der Plan für die Reise. Wer bekommt welches Auto?"},{"speaker":"Lisa","gender":"f","text":"Ich habe die Namen hier. Fünf Leute fahren und keiner will zu Fuß gehen."},{"speaker":"Lukas","gender":"m","text":"Ich nehme den Kleinwagen. Ich fahre allein in die Stadt und der Weg ist kurz."},{"speaker":"Lisa","gender":"f","text":"Nimmt jemand das Motorrad? Das ist nicht sicher."},{"speaker":"Lukas","gender":"m","text":"Ein Motorrad mietet keiner von uns. Das ist uns zu schnell."},{"speaker":"Lisa","gender":"f","text":"Ich miete den Transporter, weil ich am Samstag viele Kisten hole."},{"speaker":"Lukas","gender":"m","text":"Die Schlüssel liegen rechts. Tom will etwas ohne Dach."},{"speaker":"Lisa","gender":"f","text":"Tom mietet ein Cabrio. Bei Sonne soll der Wind durchs Haar gehen."},{"speaker":"Lukas","gender":"m","text":"Will jemand den Sportwagen an der Ecke? Der ist rot und teuer."},{"speaker":"Lisa","gender":"f","text":"Einen Sportwagen wollen wir nicht."},{"speaker":"Lukas","gender":"m","text":"Sara fährt mit den Kindern und dem Hund."},{"speaker":"Lisa","gender":"f","text":"Sara braucht den Familienwagen. Hinten ist Platz für alle und für die Tasche."},{"speaker":"Lukas","gender":"m","text":"Tim ist eine ganze Woche auf der Reise. Er schläft nicht im Hotel."},{"speaker":"Lisa","gender":"f","text":"Tim mietet das Wohnmobil. Dort sind ein Bett und eine kleine Küche."},{"speaker":"Lukas","gender":"m","text":"Das reicht für die ganze Woche."},{"speaker":"Lisa","gender":"f","text":"Ich gebe den Plan jetzt ab."}],"options":[{"letter":"a","text":"Bus"},{"letter":"b","text":"Cabrio"},{"letter":"c","text":"Wohnmobil"},{"letter":"d","text":"Motorrad"},{"letter":"e","text":"Familienwagen"},{"letter":"f","text":"Transporter"},{"letter":"g","text":"Sportwagen"},{"letter":"h","text":"Kleinwagen"},{"letter":"i","text":"Elektroauto"}],"items":[{"person":"Lukas","correct":"h"},{"person":"Lisa","correct":"f"},{"person":"Tom","correct":"b"},{"person":"Sara","correct":"e"},{"person":"Tim","correct":"c"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Kundin","gender":"f","text":"Guten Tag, was kostet das Auto pro Tag? 40 Euro, 70 Euro oder mehr?"},{"speaker":"Mitarbeiter","gender":"m","text":"Der Kleinwagen 40 Euro pro Tag, nicht 70 Euro."},{"speaker":"Kundin","gender":"f","text":"Und für eine Woche, 70 Euro am Tag?"},{"speaker":"Mitarbeiter","gender":"m","text":"Für eine Woche 210 Euro, das ist günstiger. Pro Tag bleibt es 40, nicht 70."},{"speaker":"Kundin","gender":"f","text":"Dann nehme ich den Kleinwagen für 40 Euro am Tag. Danke."}],"q":"Was kostet das Auto pro Tag?","opts":["210 Euro.","40 Euro.","70 Euro."],"correct":1},{"lines":[{"speaker":"Mann","gender":"m","text":"Guten Tag, bis wann muss ich das Auto zurückbringen? Heute Abend oder übermorgen?"},{"speaker":"Mitarbeiterin","gender":"f","text":"Morgen bis 18 Uhr, nicht heute Abend und nicht übermorgen."},{"speaker":"Mann","gender":"m","text":"Und wenn ich später komme, übermorgen?"},{"speaker":"Mitarbeiterin","gender":"f","text":"Dann zahlen Sie einen ganzen Tag mehr. Also morgen bis 18 Uhr, bitte nicht später."},{"speaker":"Mann","gender":"m","text":"Gut, morgen bis 18 Uhr. Heute Abend geht nicht. Danke."}],"q":"Bis wann muss er das Auto zurückbringen?","opts":["Heute Abend.","Morgen bis 18 Uhr.","Übermorgen."],"correct":1},{"lines":[{"speaker":"Frau","gender":"f","text":"Guten Tag, ist eine Versicherung dabei? Mit 100 Euro Selbstbeteiligung oder ohne, also keine?"},{"speaker":"Mitarbeiter","gender":"m","text":"Ja, aber mit 500 Euro Selbstbeteiligung, nicht 100 Euro und auch nicht null."},{"speaker":"Frau","gender":"f","text":"Kann ich die 500 Euro reduzieren, auf 100 oder auf keine?"},{"speaker":"Mitarbeiter","gender":"m","text":"Ja, für 10 Euro mehr pro Tag. Standard sind 500 Euro, nicht null."},{"speaker":"Frau","gender":"f","text":"Dann bleibe ich bei 500 Euro. Danke für die Erklärung."}],"q":"Wie hoch ist die Selbstbeteiligung?","opts":["100 Euro.","Keine.","500 Euro."],"correct":2},{"lines":[{"speaker":"Kunde","gender":"m","text":"Guten Tag, darf ich ins Ausland fahren? Nach Österreich, oder ist das verboten, oder nur mit Aufpreis?"},{"speaker":"Mitarbeiterin","gender":"f","text":"In welches Land, Österreich? Verboten ist es nicht, und Aufpreis auch nicht."},{"speaker":"Kunde","gender":"m","text":"Nach Österreich, bitte. Geht das ohne Aufpreis?"},{"speaker":"Mitarbeiterin","gender":"f","text":"Ja, das ist erlaubt, ohne Aufpreis. Nicht verboten."},{"speaker":"Kunde","gender":"m","text":"Super, dann fahre ich nach Österreich. Danke schön."}],"q":"Darf der Kunde nach Österreich fahren?","opts":["Nur mit Aufpreis.","Nein, verboten.","Ja, das ist erlaubt."],"correct":2},{"lines":[{"speaker":"Kundin","gender":"f","text":"Guten Tag, brauche ich eine Kreditkarte? Geht auch Bargeld oder eine Überweisung?"},{"speaker":"Mitarbeiter","gender":"m","text":"Ja, für die Kaution brauchen Sie eine Kreditkarte. Bargeld und Überweisung gehen nicht."},{"speaker":"Kundin","gender":"f","text":"Geht auch Bargeld für die Kaution?"},{"speaker":"Mitarbeiter","gender":"m","text":"Leider nein, nur Kreditkarte, keine Überweisung und kein Bargeld."},{"speaker":"Kundin","gender":"f","text":"Verstehe, nur Kreditkarte. Ich habe eine dabei. Danke."}],"q":"Wie zahlt man die Kaution?","opts":["Mit Kreditkarte.","Mit Bargeld.","Per Überweisung."],"correct":0}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Frau Schmitt, einer Mitarbeiterin einer Autovermietung. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporter","gender":"m","text":"Frau Schmitt, wer mietet bei Ihnen am häufigsten ein Auto?"},{"speaker":"Schmitt","gender":"f","text":"Sehr unterschiedliche Leute. Geschäftsleute auf Reisen, Familien im Urlaub, und viele Menschen, die umziehen und einen Transporter brauchen. In der Stadt haben immer weniger Leute ein eigenes Auto. Sie mieten lieber, wenn sie eins brauchen. Das ist oft günstiger."},{"speaker":"Reporter","gender":"m","text":"Was ist der häufigste Fehler der Kunden?"},{"speaker":"Schmitt","gender":"f","text":"Sie lesen den Vertrag nicht genau. Dann ärgern sie sich über Kosten, die sie nicht erwartet haben. Mein Rat: Fragen Sie immer, was im Preis dabei ist. Besonders die Versicherung ist wichtig. Ein Kratzer kann sonst sehr teuer werden, wenn man nicht gut versichert ist."},{"speaker":"Reporter","gender":"m","text":"Gibt es oft Schäden an den Autos?"},{"speaker":"Schmitt","gender":"f","text":"Kleinere schon, vor allem Kratzer beim Parken. Große Unfälle sind selten, zum Glück. Wir prüfen jedes Auto genau, wenn es zurückkommt. Deshalb mein Tipp: Machen Sie bei der Abholung Fotos vom Auto. Dann gibt es später keinen Streit über alte Kratzer, die schon da waren."},{"speaker":"Reporter","gender":"m","text":"Wie ist es mit Elektroautos?"},{"speaker":"Schmitt","gender":"f","text":"Danach fragen immer mehr Kunden. Wir haben schon einige, und es werden mehr. Viele wollen sie einfach mal ausprobieren, bevor sie selbst eins kaufen. Das Aufladen ist für manche noch ungewohnt, aber das erklären wir gern. Die Zukunft gehört sicher dem Elektroauto."},{"speaker":"Reporter","gender":"m","text":"Was raten Sie Ihren Kunden?"},{"speaker":"Schmitt","gender":"f","text":"Buchen Sie früh, besonders in der Urlaubszeit, dann ist es billiger und die Auswahl größer. Geben Sie das Auto vollgetankt und sauber zurück, das spart Geld. Und prüfen Sie das Auto vor der Fahrt. Wenn alle das beachten, läuft die Miete für beide Seiten reibungslos."}],"items":[{"q":"In der Stadt haben immer weniger Leute ein eigenes Auto.","correct":"ja"},{"q":"Frau Schmitt findet, die Versicherung sei unwichtig.","correct":"nein"},{"q":"Sie rät, bei der Abholung Fotos vom Auto zu machen.","correct":"ja"},{"q":"Nach Elektroautos fragen immer mehr Kunden.","correct":"ja"},{"q":"Sie empfiehlt, das Auto leer und schmutzig zurückzugeben.","correct":"nein"}]}]};
